PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS subject_class_assignments (id TEXT PRIMARY KEY, school_id TEXT NOT NULL REFERENCES schools(id), subject_id TEXT NOT NULL REFERENCES subjects(id), class_id TEXT NOT NULL REFERENCES classes(id), academic_year_id TEXT REFERENCES academic_years(id), active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(school_id, subject_id, class_id, academic_year_id));
CREATE TABLE IF NOT EXISTS academic_score_records (id TEXT PRIMARY KEY, school_id TEXT NOT NULL REFERENCES schools(id), record_type TEXT NOT NULL CHECK (record_type IN ('TERMINAL', 'MOCK')), mock_label TEXT, academic_year_id TEXT NOT NULL REFERENCES academic_years(id), term_id TEXT NOT NULL REFERENCES terms(id), class_id TEXT NOT NULL REFERENCES classes(id), student_id TEXT NOT NULL REFERENCES student_profiles(id), subject_id TEXT NOT NULL REFERENCES subjects(id), ca_score NUMERIC(6,2) NOT NULL DEFAULT 0, ca_max NUMERIC(6,2) NOT NULL DEFAULT 50, examination_score NUMERIC(6,2) NOT NULL DEFAULT 0, examination_max NUMERIC(6,2) NOT NULL DEFAULT 50, total_score NUMERIC(6,2) NOT NULL, grade TEXT, remark TEXT, entered_by TEXT NOT NULL REFERENCES users(id), updated_at TEXT NOT NULL, UNIQUE(school_id, record_type, mock_label, academic_year_id, term_id, class_id, student_id, subject_id));
CREATE TABLE IF NOT EXISTS result_signatures (id TEXT PRIMARY KEY, school_id TEXT NOT NULL REFERENCES schools(id), signatory_role TEXT NOT NULL, storage_key TEXT, mime_type TEXT NOT NULL, document_size INTEGER NOT NULL DEFAULT 0, active INTEGER NOT NULL DEFAULT 1, uploaded_by TEXT NOT NULL REFERENCES users(id), uploaded_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_academic_scores_lookup ON academic_score_records(school_id, record_type, academic_year_id, term_id, class_id, student_id);
CREATE INDEX IF NOT EXISTS idx_subject_class_assignments_lookup ON subject_class_assignments(school_id, class_id, academic_year_id, active);
CREATE UNIQUE INDEX IF NOT EXISTS uq_active_result_signature ON result_signatures(school_id, signatory_role) WHERE active = 1;
